export const COMPANIONS=[
{id:'slime',kind:'pet',name:'Lúmi, Gota Astral',cell:0,gold:25000,cash:500,minLevel:5,description:'Slime cristalino que fortalece ataque e reserva de mana.',focus:'Ataque + MP'},
{id:'fox',kind:'pet',name:'Aelys, Raposa Lunar',cell:1,gold:75000,cash:1500,minLevel:25,description:'Raposa de três caudas. Precisão e dano crítico.',focus:'Precisão + dano crítico'},
{id:'drake',kind:'pet',name:'Nyx, Draco do Vazio',cell:2,gold:150000,cash:3000,minLevel:75,description:'Draco de obsidiana que amplia habilidades de espada e magia.',focus:'Ampliação de espada + magia'},
{id:'wolf',kind:'mount',name:'Argos, Lobo de Prata',cell:3,gold:50000,cash:2000,minLevel:10,description:'Lobo de sela rúnica. Aumenta HP e defesa.',focus:'HP + defesa'},
{id:'panther',kind:'mount',name:'Vesper, Pantera Astral',cell:4,gold:250000,cash:5000,minLevel:50,description:'Pantera do eclipse. Penetração e precisão.',focus:'Penetração + precisão'},
{id:'stag',kind:'mount',name:'Auréon, Cervo Solar',cell:5,gold:400000,cash:8000,minLevel:100,description:'Cervo de cristal. HP e reserva mágica.',focus:'HP + MP'}];
export const SIGIL_TIERS=['Centelha','Desperto','Arcano','Soberano','Divino','Origem Infinita'];
export function initCompanions(p){p.companions||={owned:{},pet:null,mount:null,mounted:false};p.companions.owned||={};p.magicula||={rank:0};p.materials||={};p.wallet||={cash:0};}
export function companionBonuses(p){const c=p.companions||{},out={attackPct:0,hpPct:0,defensePct:0,mpPct:0,critd:0,amp:0,pen:0,accuracy:0,speed:0};for(const kind of ['pet','mount']){const id=c[kind],entry=c.owned?.[id];if(!entry)continue;const r=Math.min(500,Math.max(1,entry.rank||1));if(id==='slime'){out.attackPct+=.01+r*.0003;out.mpPct+=.02+r*.0005;}if(id==='fox'){out.critd+=.01+r*.0003;out.accuracy+=20+r*2;}if(id==='drake')out.amp+=.01+r*.0003;if(id==='wolf'){out.hpPct+=.02+r*.0004;out.defensePct+=.01+r*.0003;}if(id==='panther'){out.pen+=10+r;out.accuracy+=30+r*2;}if(id==='stag'){out.hpPct+=.02+r*.0004;out.mpPct+=.04+r*.0006;}if(kind==='mount'&&c.mounted)out.speed=.25+r*.0005;}return out;}
export function magiculaBonuses(p){const r=Math.max(0,Math.min(500,p.magicula?.rank||0));return {attackPct:r*.0009,hpPct:r*.0006,pen:r*2,pressure:r*.0002};}
export function magiculaAmount(power,rank){return Math.round(Math.max(0,power)*(1+Math.min(500,Math.max(0,rank))/100)/10);}
export function magiculaTier(rank){return Math.min(5,Math.floor(Math.max(0,rank)/100));}
export function unlockCompanion(p,id,currency='gold'){initCompanions(p);const d=COMPANIONS.find(v=>v.id===id);if(!d||!['gold','cash'].includes(currency))return {ok:false,reason:'Aquisição inválida.'};if(p.companions.owned[id])return {ok:false,reason:'Companheiro já adquirido.'};if(p.level<d.minLevel)return {ok:false,reason:'Requer nível '+d.minLevel+'.'};const balance=currency==='gold'?p.gold:p.wallet.cash;if(balance<d[currency])return {ok:false,reason:currency==='gold'?'Ouro insuficiente.':'Cash insuficiente.'};if(currency==='gold')p.gold-=d.gold;else p.wallet.cash-=d.cash;p.companions.owned[id]={rank:1};p.companions[d.kind]=id;return {ok:true};}
export function equipCompanion(p,kind,id){initCompanions(p);if(!['pet','mount'].includes(kind))return {ok:false,reason:'Tipo inválido.'};if(id&&(!p.companions.owned[id]||!COMPANIONS.some(d=>d.id===id&&d.kind===kind)))return {ok:false,reason:'Companheiro não adquirido.'};p.companions[kind]=id||null;if(kind==='mount')p.companions.mounted=false;return {ok:true};}
export function growthCost(p,kind,id=null){const entry=kind==='magicula'?p.magicula:p.companions?.owned?.[id],rank=entry?.rank||0,n=rank+1;return {rank:n,level:Math.max(kind==='magicula'?1:5,Math.ceil(n*2)),gold:(kind==='magicula'?800:250)*n*n,material:kind==='magicula'?'Fragmento de Magícula':kind==='pet'?'Cristal de Vínculo':'Essência de Montaria',count:Math.ceil((kind==='magicula'?4:3)*n**1.2)};}
export function growthQuote(p,kind,id=null){if(!['pet','mount','magicula'].includes(kind))return {ok:false,reason:'Evolução inválida.'};const d=COMPANIONS.find(v=>v.id===id);if(kind!=='magicula'&&(!p.companions?.owned?.[id]||d?.kind!==kind))return {ok:false,reason:'Adquira o companheiro primeiro.'};const entry=kind==='magicula'?p.magicula:p.companions.owned[id];if((entry?.rank||0)>=500)return {ok:false,reason:'Evolução máxima500.'};const cost=growthCost(p,kind,id);if(p.level<cost.level)return {ok:false,reason:'Requer nível '+cost.level+'.'};const missing=Math.max(0,cost.count-(p.materials?.[cost.material]||0)),gold=Math.max(0,cost.gold-p.gold);return {ok:true,cost,missing,gold,price:150+missing*10+Math.ceil(gold/50)};}
export function growCompanion(p,kind,id=null,currency='materials'){initCompanions(p);const q=growthQuote(p,kind,id);if(!q.ok)return q;if(!['materials','cash'].includes(currency))return {ok:false,reason:'Moeda inválida.'};if(currency==='materials'&&(q.missing||q.gold))return {ok:false,reason:'Faltam ouro ou materiais.'};if(currency==='cash'&&p.wallet.cash<q.price)return {ok:false,reason:'Cash insuficiente.'};if(currency==='cash'){p.wallet.cash-=q.price;p.gold+=q.gold;p.materials[q.cost.material]=(p.materials[q.cost.material]||0)+q.missing;}p.gold-=q.cost.gold;p.materials[q.cost.material]-=q.cost.count;const entry=kind==='magicula'?p.magicula:p.companions.owned[id];entry.rank=q.cost.rank;return {ok:true,rank:entry.rank};}
export function toggleMount(p,inCombat=false){initCompanions(p);if(inCombat)return {ok:false,reason:'Saia de combate para montar.'};if(!p.companions.mount||!p.companions.owned[p.companions.mount])return {ok:false,reason:'Adquira e equipe uma montaria.'};p.companions.mounted=!p.companions.mounted;return {ok:true,mounted:p.companions.mounted};}
export const SUPPLIES=[{id:'cores',name:'Cristais de aprimoramento ×50',price:400,field:'shards',count:50},{id:'runes',name:'Núcleos de atributo ×10',price:800,field:'runes',count:10},{id:'bond',name:'Cristal de Vínculo ×100',price:800,material:'Cristal de Vínculo',count:100},{id:'mount-essence',name:'Essência de Montaria ×100',price:800,material:'Essência de Montaria',count:100},{id:'magic-fragments',name:'Fragmento de Magícula ×100',price:1000,material:'Fragmento de Magícula',count:100},{id:'cataclysm',name:'Núcleos de Cataclismo ×10',price:10000,material:'Núcleo de Cataclismo',count:10}];
export function buySupply(p,id){initCompanions(p);const d=SUPPLIES.find(v=>v.id===id);if(!d)return {ok:false,reason:'Produto inválido.'};if(p.wallet.cash<d.price)return {ok:false,reason:'Cash insuficiente.'};p.wallet.cash-=d.price;if(d.field)p[d.field]=(p[d.field]||0)+d.count;else p.materials[d.material]=(p.materials[d.material]||0)+d.count;return {ok:true};}

SUPPLIES.push({id:'relic-fragments',name:'Fragmento de Relíquia ×100',price:12000,material:'Fragmento de Relíquia',count:100},{id:'star-dust',name:'Poeira de Constelação ×100',price:15000,material:'Poeira de Constelação',count:100},{id:'soul-crystals',name:'Cristal da Alma ×100',price:1500,material:'Cristal da Alma',count:100});
